const crypto = require('crypto');
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || $input.first().json;

const signatureHeader = headers['x-paimana-signature'] || headers['X-PAIMANA-Signature'];
const eventIdHeader = headers['x-paimana-event-id'] || headers['X-PAIMANA-Event-ID'];
const secret = $env.N8N_WEBHOOK_SECRET || 'paimana-n8n-alert-secret-key-2026';

let isValid = false;
if (signatureHeader && secret) {
  const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex');
  // Constant time comparison if lengths match
  if (signatureHeader.length === expectedSig.length) {
    isValid = crypto.timingSafeEqual(Buffer.from(signatureHeader), Buffer.from(expectedSig));
  }
} else {
  // If secret not configured in local dev, allow with warning flag
  isValid = !process.env.STRICT_HMAC_REQUIRED;
}

return [{
  json: {
    raw_payload: body,
    headers: headers,
    signature_valid: isValid,
    event_id: body.event_id || eventIdHeader,
    received_at: new Date().toISOString()
  }
}];

const item = $input.first().json;
const p = item.raw_payload || {};

if (!item.signature_valid && process.env.STRICT_HMAC_REQUIRED) {
  return [{
    json: {
      ok: false,
      error: 'invalid_signature',
      event_id: item.event_id,
      status: 'rejected'
    }
  }];
}

// Mandatory field validation
const eventId = p.event_id || item.event_id;
const eventType = p.event_type || 'THRESHOLD_CROSSED';
const projectCode = p.project?.project_code || p.project?.project_id || p.project_id;
const currentDphis = p.risk?.current_dphis !== undefined ? p.risk.current_dphis : p.current_dphis;
const recipientEmail = p.recipient?.email || p.user?.email;

if (!eventId || !projectCode || currentDphis === undefined || !recipientEmail) {
  return [{
    json: {
      ok: false,
      error: 'malformed_payload',
      details: 'Missing mandatory fields: event_id, project_code, current_dphis, or recipient.email',
      event_id: eventId,
      status: 'rejected'
    }
  }];
}

return [{
  json: {
    ok: true,
    validated: true,
    event_id: eventId,
    event_type: eventType,
    project: p.project || { project_code: projectCode, project_name: p.project_name || projectCode },
    risk: p.risk || { current_dphis: currentDphis, previous_dphis: p.previous_dphis, threshold: p.threshold || 70.0 },
    recipient: p.recipient || { email: recipientEmail, name: p.user?.name || 'Project Officer' },
    predictions: p.predictions || {},
    progress: p.progress || {},
    events: p.events || [eventType],
    explanations: p.explanations || {},
    peer_intelligence: p.peer_intelligence || { available: false },
    investigation: p.investigation || {},
    links: p.links || { project_url: p.project_url },
    metadata: p.metadata || {}
  }
}];

const item = $input.first().json;
if (!item.ok) {
  return [{ json: item }];
}

// Static data idempotency store
const staticData = $getWorkflowStaticData('global');
staticData.processedEvents = staticData.processedEvents || {};

const eventId = item.event_id;
const now = Date.now();

// Prune events older than 48 hours
for (const id in staticData.processedEvents) {
  if (now - staticData.processedEvents[id] > 48 * 3600 * 1000) {
    delete staticData.processedEvents[id];
  }
}

if (staticData.processedEvents[eventId]) {
  return [{
    json: {
      ok: true,
      event_id: eventId,
      status: 'duplicate',
      is_duplicate: true,
      message: 'Duplicate event_id detected and suppressed.'
    }
  }];
}

// Register event ID
staticData.processedEvents[eventId] = now;
item.is_duplicate = false;
return [{ json: item }];

const item = $input.first().json;
if (!item.ok || item.is_duplicate) {
  return [{ json: item }];
}

const p = item.project || {};
const r = item.risk || {};
const pred = item.predictions || {};
const prog = item.progress || {};
const peer = item.peer_intelligence || {};
const links = item.links || {};
const expl = item.explanations || {};

const projectName = p.project_name || p.project_code || 'Infrastructure Project';
const recipientName = item.recipient?.name || 'Project Stakeholder';
const currD = r.current_dphis ?? 75.0;
const prevD = r.previous_dphis ?? 60.0;
const thresh = r.threshold ?? 70.0;
const tier = r.risk_tier || 'High';

// Build deterministic fallback email
const subject = `[PAIMANA ALERT] ${projectName} — DPHIS threshold crossed`;

let peerBlock = '';
if (peer.available) {
  peerBlock = `\nPeer context:\n- Comparable projects: ${peer.peer_count || 0}\n- Peer median DPHIS: ${peer.peer_median_dphis || 'N/A'}\n- Relative deviation: +${peer.peer_deviation || 0} pts`;
} else {
  peerBlock = '\nPeer context:\n- Peer comparison was not used because insufficient comparable projects were available.';
}

const invUrl = links.investigation_url || `https://paimana-seven.vercel.app?investigation=${p.project_code}`;
const projUrl = links.project_url || `https://paimana-seven.vercel.app?project=${p.project_code}`;

const fallbackText = `Dear ${recipientName},

InfraBuild-AI's continuous monitoring system has detected a significant change in the following project:

Project:
${projectName}

Project Code:
${p.project_code}

Current DPHIS:
${currD} / 100

Previous DPHIS:
${prevD} / 100

Configured Threshold:
${thresh} / 100

Risk Tier:
${tier}

Trigger:
${item.event_type || 'THRESHOLD_CROSSED'}

Key observed signals:
- Observed expenditure vs physical progress gap: ${prog.expenditure_pct || 0}% vs ${prog.physical_progress_pct || 0}%
- Milestone timeline deviation: +${pred.predicted_schedule_slippage_months || 0} months

Predictive indicators:
- Predicted cost overrun: ${pred.predicted_cost_overrun_pct || 0}%
- Predicted schedule slippage: +${pred.predicted_schedule_slippage_months || 0} months
- Physical progress: ${prog.physical_progress_pct || 0}%
- Expenditure: ${prog.expenditure_pct || 0}%
${peerBlock}

Root-cause drivers:
${expl.summary || 'Detailed risk drivers identified in project dossier.'}

An investigation can be reviewed here:
${invUrl}

Project details:
${projUrl}

Regards,
InfraBuild-AI Monitoring System`;

const systemPrompt = `You are writing an infrastructure project monitoring alert for an authorized project stakeholder.

Use only the structured facts supplied in the input.
Do not invent facts.
Do not claim causal certainty unless the evidence explicitly supports it.
Clearly distinguish observed facts from possible explanations.
Be concise and professional.
The purpose of the email is to inform the recipient that a monitoring condition has been detected and direct them to the relevant project/investigation page.`;

return [{
  json: {
    ...item,
    system_prompt: systemPrompt,
    prompt_input: JSON.stringify(item, null, 2),
    fallback_subject: subject,
    fallback_body: fallbackText
  }
}];

