const item = $('05 — Build AI Context').first().json;
if (!item.ok || item.is_duplicate) {
  return [{ json: item }];
}

let subject = item.fallback_subject;
let body = item.fallback_body;
let generator = 'deterministic_fallback';

try {
  const aiResponse = $input.first().json;
  if (aiResponse && aiResponse.choices && aiResponse.choices.length > 0) {
    const parsed = JSON.parse(aiResponse.choices[0].message.content);
    if (parsed.subject && parsed.text_content) {
      subject = parsed.subject;
      body = parsed.text_content;
      generator = 'openai_chatgpt';
    }
  }
} catch (e) {
  generator = 'fallback_due_to_parse_error';
}

// Convert body to clean responsive HTML email
const htmlBody = `
<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 24px; border: 1px solid #e2e8f0; border-radius: 8px; background: #ffffff; color: #0f172a;">
  <div style="border-bottom: 2px solid #ef4444; padding-bottom: 12px; margin-bottom: 18px;">
    <h2 style="margin: 0; color: #0f172a; font-size: 18px; font-weight: 700;">InfraBuild-AI <span style="font-size: 11px; background: #fee2e2; color: #dc2626; padding: 3px 8px; border-radius: 999px; margin-left: 6px;">ALERT</span></h2>
  </div>
  <div style="white-space: pre-wrap; font-size: 14px; line-height: 1.6; color: #334155;">${body}</div>
  <div style="margin-top: 24px; padding-top: 14px; border-top: 1px solid #e2e8f0; font-size: 11px; color: #94a3b8;">
    Generated via ${generator} · InfraBuild-AI Sovereign Continuous Monitoring Engine · Human review required for consequential actions
  </div>
</div>`;

return [{
  json: {
    ...item,
    email_subject: subject,
    email_text: body,
    email_html: htmlBody,
    email_generator: generator
  }
}];

const item = $('07 — Validate Email Content').first().json;
if (!item.ok || item.is_duplicate) {
  return [{ json: item }];
}

const sendResult = $input.first().json;
const sendFailed = sendResult && sendResult.error;
const emailStatus = sendFailed ? 'failed' : 'sent';

return [{
  json: {
    event_id: item.event_id,
    project_code: item.project?.project_code,
    recipient: item.recipient?.email,
    event_type: item.event_type,
    generated_at: new Date().toISOString(),
    email_status: emailStatus,
    email_generator: item.email_generator,
    provider_reference: sendResult?.messageId || sendResult?.id || (sendFailed ? sendResult.error.message : 'SENT-SUCCESS')
  }
}];
